// Simple math helpers.
export function add(a, b) {
  return a + b;
}

export function sub(a, b) {
  return a - b;
}

export function mul(a, b) {
  return a * b;
}

export function div(a, b) {
  if (b === 0) throw new Error('division by zero');
  return a / b;
}

export function mod(a, b) {
  // Euclidean modulo — result always has the sign of b (or zero).
  const r = a % b;
  return r < 0 && b > 0 ? r + b : r > 0 && b < 0 ? r + b : r;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { add, sub, mul, div, mod } from '../src/math.mjs';

test('add', () => { assert.equal(add(2, 3), 5); });
test('sub', () => { assert.equal(sub(5, 2), 3); });
test('mul', () => { assert.equal(mul(4, 3), 12); });
test('div', () => { assert.equal(div(10, 2), 5); });
test('div by zero', () => {
  assert.throws(() => div(1, 0), /division by zero/);
});
test('mod positive', () => { assert.equal(mod(10, 3), 1); });
test('mod negative', () => { assert.equal(mod(-1, 4), 3); });
